package app

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/liamg/oriel/registry"
	"github.com/liamg/oriel/render"
)

// searchScene has a few Go files, one marked generated by .gitattributes, in a work dir.
func searchScene(t *testing.T) (*errScene, string) {
	dir := t.TempDir()
	for name, body := range map[string]string{
		".gitattributes":            "gen/** linguist-generated\n",
		"internal/pricing/round.go": "package pricing\n\nfunc Round(v int) int { return v * 100 }\n\nfunc RoundMinor(v int) int { return Round(v) / 100 }\n",
		"internal/pricing/tiers.go": "package pricing\n\nfunc tier() int { return Round(3) }\n",
		"gen/api.go":                "package gen\n\nfunc Round() {}\n",
	} {
		p := filepath.Join(dir, name)
		os.MkdirAll(filepath.Dir(p), 0o755)
		os.WriteFile(p, []byte(body), 0o644)
	}
	s := newScene(t, "", dir, mockupSize)
	return s, dir
}

func (s *errScene) search() *projectSearch {
	for _, e := range s.exts {
		if x, ok := e.(*projectSearch); ok {
			return x
		}
	}
	return nil
}

// typeInto clicks the input labelled label and types text into it.
func (s *errScene) typeInto(t *testing.T, label, text string) {
	t.Helper()
	s.click(centre(s.access(label).Bounds))
	for _, r := range text {
		s.ui.Key(render.KeyEvent{Key: string(r)})
		s.frame()
	}
}

// waitSearch frames until the search finished and the frame has want.
func (s *errScene) waitSearch(t *testing.T, want string) string {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		s.search().wait()
		s.frame()
		text := s.frameText()
		if strings.Contains(text, want) {
			return text
		}
		if time.Now().After(deadline) {
			t.Fatalf("no %q:\n%s", want, text)
		}
	}
}

// FG-3: project search: the rail's Search opens the panel, a PCRE2 query streams its matches grouped by file, and
// generated files are left out unless the query starts "@all ".
func TestProjectSearch(t *testing.T) {
	s, _ := searchScene(t)
	s.frame()
	s.click(railAt(1))
	s.frame()
	if !s.showing(SearchView) {
		t.Fatal("the rail's Search didn't open the search panel")
	}
	s.typeInto(t, "Find", `(?<=return )Round\(`)
	text := s.waitSearch(t, "2 in 2 files")
	for _, want := range []string{"internal/pricing/round.go", "internal/pricing/tiers.go", "5", "func RoundMinor(v int) int { return ", "Round(", "v) / 100 }"} {
		if !strings.Contains(text, want) {
			t.Errorf("results lack %q:\n%s", want, text)
		}
	}
	if strings.Contains(text, "gen/api.go") {
		t.Error("a generated file was searched")
	}
	s.run("search.open", registry.Args{"query": "@all Round"})
	text = s.waitSearch(t, "gen/api.go")
	if !strings.Contains(text, "in 3 files") {
		t.Errorf("@all didn't search every file:\n%s", text)
	}
}

// Enter on a match opens its file at its line.
func TestSearchOpensMatches(t *testing.T) {
	s, dir := searchScene(t)
	s.run("search.open", registry.Args{"query": "tier\\("})
	s.waitSearch(t, "1 in 1 file")
	s.clickText(t, "tier(")
	s.frame()
	p := s.editor().current()
	if filepath.Join(dir, p.Name()) != filepath.Join(dir, "internal/pricing/tiers.go") || p.Cursor().Line != 2 {
		t.Errorf("opened %s at line %d", p.Name(), p.Cursor().Line+1)
	}
}

// FG-3: "replace shows a diff before applying": Replace all… opens the diff of every file it would change and
// writes nothing; Apply writes the files, and an open buffer is changed in the buffer, as one undoable step.
func TestReplacePreviewThenApply(t *testing.T) {
	s, dir := searchScene(t)
	s.run("editor.open", registry.Args{"path": filepath.Join(dir, "internal/pricing/tiers.go")})
	s.run("search.open", nil)
	s.frame()
	s.frame()
	s.typeInto(t, "Find", `Round(\w*)\(`)
	s.typeInto(t, "Replace", `Rounded$1(`)
	s.waitSearch(t, "4 in 2 files")
	if !strings.Contains(s.frameText(), "RoundedMinor(") {
		t.Errorf("the results don't preview the replacement:\n%s", s.frameText())
	}
	s.click(centre(s.access("Replace all…").Bounds))
	s.frame()
	s.frame()
	if !s.showing(ReplaceView) {
		t.Fatal("Replace all… didn't show the diff")
	}
	text := s.frameText()
	for _, want := range []string{"4 replacements in 2 files", "- func Round(v int) int { return v * 100 }", "+ func Rounded(v int) int { return v * 100 }",
		"- func tier() int { return Round(3) }", "+ func tier() int { return Rounded(3) }"} {
		if !strings.Contains(text, want) {
			t.Errorf("the diff lacks %q:\n%s", want, text)
		}
	}
	if b, _ := os.ReadFile(filepath.Join(dir, "internal/pricing/round.go")); strings.Contains(string(b), "Rounded") {
		t.Fatal("the preview wrote a file")
	}
	s.click(centre(s.access("Apply").Bounds))
	s.frame()
	b, _ := os.ReadFile(filepath.Join(dir, "internal/pricing/round.go"))
	if want := "package pricing\n\nfunc Rounded(v int) int { return v * 100 }\n\nfunc RoundedMinor(v int) int { return Rounded(v) / 100 }\n"; string(b) != want {
		t.Errorf("round.go after Apply:\n%s", b)
	}
	if b, _ := os.ReadFile(filepath.Join(dir, "internal/pricing/tiers.go")); strings.Contains(string(b), "Rounded") {
		t.Error("the open tiers.go was written on disk rather than changed in its buffer")
	}
	s.run("editor.open", registry.Args{"path": filepath.Join(dir, "internal/pricing/tiers.go")})
	s.frame()
	if got := s.line(2); got != "func tier() int { return Rounded(3) }" {
		t.Errorf("tiers.go's buffer: %q", got)
	}
	s.keys("u")
	if got := s.line(2); got != "func tier() int { return Round(3) }" {
		t.Errorf("u didn't undo the replace: %q", got)
	}
	if s.showing(ReplaceView) {
		t.Error("the diff stayed open after Apply")
	}
}
